// Robust instant PetGrow home content mount. Uses the stable .dash-quick-grid anchor.
const ROOT_ID='petgrow-home-fast-content';
const CACHE_KEY='petgrow_home_feed_v4';
const tips=[
['건강','물 섭취량이 평소와 달라졌다면 확인해요'],['생활','산책 후 발바닥 관리, 이렇게 해요'],['식단','사료는 갑자기 바꾸지 말고 천천히 교체해요'],['행동','자꾸 핥는 행동, 언제 주의해야 할까요?'],['건강','귀를 자주 긁을 때 살펴볼 부분'],['생활','초보 보호자가 놓치기 쉬운 집안 안전 체크'],['식단','간식은 하루 급여량 안에서 조절해요'],['행동','낯선 사람과의 사회화는 천천히 시작해요'],['건강','구토 색과 횟수로 먼저 체크할 포인트']
];
let feed=null,audio=null,playing='';
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
function read(){try{return JSON.parse(localStorage.getItem(CACHE_KEY)||'null')}catch{return null}}
function save(v){try{localStorage.setItem(CACHE_KEY,JSON.stringify(v))}catch{}}
function go(label){const els=$$('button,a').filter(x=>!x.closest('#'+ROOT_ID));const el=els.find(x=>(x.textContent||'').trim().includes(label));el?.click?.()}
function card(title,sub,on){const b=document.createElement('button');b.type='button';b.className='bg-card';b.style.cssText='padding:14px 15px;text-align:left;border:1px solid var(--border);cursor:pointer;width:100%';b.innerHTML=`<small style="font-weight:800;color:var(--primary)">${sub||''}</small><div style="font-weight:800;font-size:14px;line-height:1.5;margin-top:5px">${title||''}</div>`;b.onclick=on;return b}
function head(title,label){const d=document.createElement('div');d.className='dash-section-head';d.innerHTML=`<h2>${title}</h2>`;const b=document.createElement('button');b.type='button';b.className='bg-chip';b.textContent='전체보기';b.onclick=()=>go(label);d.appendChild(b);return d}
function mount(){const quick=$('.dash-quick-grid');if(!quick)return false;const sec=quick.closest('section');if(!sec)return false;let root=$('#'+ROOT_ID);if(!root){root=document.createElement('div');root.id=ROOT_ID;root.style.cssText='display:grid;gap:18px;margin:18px 0';sec.insertAdjacentElement('afterend',root)}
  const day=Math.floor((Date.now()+9*3600000)/86400000),start=(day*3)%tips.length;
  root.replaceChildren();
  const info=document.createElement('section');info.className='dash-section';info.appendChild(head('오늘의 Pet정보','Pet정보'));const ig=document.createElement('div');ig.style.cssText='display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px';[0,1,2].forEach(i=>{const t=tips[(start+i)%tips.length];ig.appendChild(card(t[1],t[0],()=>go('Pet정보')))});info.appendChild(ig);root.appendChild(info);
  const music=document.createElement('section');music.className='dash-section';music.appendChild(head('인기 Pet음악 TOP 5','Pet음악'));const ml=document.createElement('div');ml.style.cssText='display:grid;gap:9px';const tracks=Array.isArray(feed?.top5)?feed.top5:[];if(!tracks.length){ml.innerHTML='<div class="bg-card" style="padding:14px">인기 음악을 불러오는 중…</div>'}else tracks.slice(0,5).forEach((t,i)=>{const r=document.createElement('div');r.className='bg-card';r.style.cssText='padding:10px 12px;border:1px solid var(--border);display:grid;grid-template-columns:32px 1fr auto;gap:10px;align-items:center';r.innerHTML=`<b style="text-align:center;color:var(--primary)">${i+1}</b><button type="button" style="border:0;background:transparent;text-align:left;font:inherit;min-width:0;cursor:pointer"><b style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${t.title||'Pet음악'}</b><small class="bg-sub">▶ ${Number(t.playCount||0).toLocaleString()} · ♥ ${Number(t.likeCount||0).toLocaleString()}</small></button>`;r.children[1].onclick=()=>go('Pet음악');const p=document.createElement('button');p.type='button';p.className='bg-chip';p.textContent=playing===String(t.id)?'❚❚':'▶';p.onclick=async()=>{const id=String(t.id),url=t.audioUrl||'';if(!url)return go('Pet음악');if(audio&&playing===id&&!audio.paused){audio.pause();playing='';mount();return}try{audio?.pause?.()}catch{}audio=new Audio(url);playing=id;audio.onended=()=>{playing='';mount()};audio.onerror=()=>{playing='';mount()};mount();try{await audio.play();fetch('/api/music?action=play',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:t.id})}).catch(()=>{})}catch{playing='';mount()}};r.appendChild(p);ml.appendChild(r)});music.appendChild(ml);root.appendChild(music);
  const news=document.createElement('section');news.className='dash-section';news.appendChild(head('최신 Pet뉴스','Pet뉴스'));const nl=document.createElement('div');nl.style.cssText='display:grid;gap:9px';const ns=Array.isArray(feed?.news)?feed.news:[];if(!ns.length){nl.innerHTML='<div class="bg-card" style="padding:14px">최신 뉴스를 불러오는 중…</div>'}else ns.slice(0,3).forEach(n=>nl.appendChild(card(n.title,`${n.category||'Pet뉴스'}${n.source?' · '+n.source:''}`,()=>go('Pet뉴스'))));news.appendChild(nl);root.appendChild(news);
  $$('.dash-section-head h2').forEach(h=>{if((h.textContent||'').includes('주요 Pet뉴스')){const s=h.closest('section');if(s&&!s.closest('#'+ROOT_ID))s.style.display='none'}});return true}
async function refresh(){try{const r=await fetch('/api/home-feed',{cache:'force-cache'});if(!r.ok)return;const j=await r.json();feed={news:Array.isArray(j.news)?j.news:[],top5:Array.isArray(j.top5)?j.top5:[]};save(feed);mount()}catch{}}
function boot(){feed=read()||{news:[],top5:[]};mount();refresh();let tries=0;const t=setInterval(()=>{mount();if(++tries>30)clearInterval(t)},250);new MutationObserver(()=>mount()).observe(document.getElementById('root')||document.body,{childList:true,subtree:true})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
